import{_ as r,l as n,o as e,c as l,v as o,p as m,x as t,d as s,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"生产函数估计","description":"","frontmatter":{"title":"生产函数估计","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/production-function-estimation.md","filePath":"econ/production-function-estimation.md","lastUpdated":1789023840000}'),E={name:"econ/production-function-estimation.md"};function p(_,a,h,A,g,u){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="生产函数估计" tabindex="-1">生产函数估计 <a class="header-anchor" href="#生产函数估计" aria-label="Permalink to &quot;生产函数估计&quot;">​</a></h1><div class="epigraph"><p>厂商看见生产率再选投入，OLS 把高 $\\omega$ 的多雇劳动算进劳动弹性；要用投资或中间投入当代理，把 $\\omega$ 从残差里赶出来，规模报酬才不是会计恒等。</p><footer>—— Olley and Pakes, The Dynamics of Productivity in the Telecommunications Equipment Industry, Econometrica 1996；Levinsohn and Petrin, RES 2003；Ackerberg, Caves and Frazer, Econometrica 2015</footer></div><p><a href="/econ/blp-demand">上一课</a>在产品空间估需求。本课换厂商技术：\\(Q=F(K,L)\\mathrm{e}^{\\omega}\\)。拍卖下一课换另一套结构（出价规则）。本课钉生产函数的内生投入与代理方法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对数产出 \\(y_{it}=\\beta_k k_{it}+\\beta_l l_{it}+\\omega_{it}+\\varepsilon_{it}\\)。\\(\\omega\\) 是厂商知道的生产率，\\(\\varepsilon\\) 是事后冲击。高 \\(\\omega\\) 的厂多雇 \\(L\\)、多投 \\(K\\)，OLS 高估投入弹性，规模报酬被夸大，Solow 残差被压小。缺口不是再讲<a href="/econ/solow-residual">索洛残差</a>宏观核算，而是微观：选择投入的信息集。Olley–Pakes：投资 \\(i_{it}=i(k_{it},\\omega_{it})\\) 在单调下可反演 \\(\\omega=h(k,i)\\)，非参数第一阶段把 \\(\\omega\\) 收进函数，第二阶段用存活与 \\(k\\) 的定律识别 \\(\\beta_k\\)。Levinsohn–Petrin 用中间投入代替投资（投资经常为零）。Ackerberg–Caves–Frazer：若劳动也在 \\(\\omega\\) 之后灵活选择，第一阶段不能识别 \\(\\beta_l\\)，要改时序假设。</p><p><span class="marginnote">固定效应只吸时不变 \\(\\omega\\)。生产率的 Markov 冲击正是 OP 要捕的。FE 与 OP 不是替代口号，是对 \\(\\omega\\) 过程的不同假设。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明时序：资本预定、劳动与中间投入是否同期对 \\(\\omega\\) 反应。代理：投资或中间投入严格单调于 \\(\\omega\\)。第二阶段 GMM：创新 \\(\\xi_{it}=\\omega_{it}-\\mathbb{E}[\\omega_{it}\\mid\\omega_{i,t-1}]\\) 与预定工具正交。退出：OP 用存活概率修正选择（低 \\(\\omega\\) 退出使样本里 \\(\\omega\\) 截断）。</p>',8)),(e(),m(d,null,{default:t(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OMEGA%5B%22%E5%8E%82%E5%95%86%E7%9C%8B%E8%A7%81%20%CF%89%22%5D%20--%3E%20INPUT%5B%22%E9%80%89%E6%8B%A9%20L%2C%20I%2C%20M%22%5D%0A%20%20INPUT%20--%3E%20OLS%5B%22OLS%3A%20%E5%BC%B9%E6%80%A7%E5%81%8F%E9%AB%98%22%5D%0A%20%20MON%5B%22%E4%BB%A3%E7%90%86%E5%8D%95%E8%B0%83%22%5D%20--%3E%20INV%5B%22%E5%8F%8D%E6%BC%94%20%CF%89%22%5D%0A%20%20INV%20--%3E%20GMM%5B%22%E5%AF%B9%E5%88%9B%E6%96%B0%20%CE%BE%20%E7%9A%84%E7%9F%A9%22%5D%0A%20%20ACF%5B%22%E5%8A%B3%E5%8A%A8%E4%B9%9F%E7%81%B5%E6%B4%BB%22%5D%20--%3E%20TIMING%5B%22%E6%94%B9%E6%97%B6%E5%BA%8F%2C%20%E5%90%A6%E5%88%99%20%CE%B2_l%20%E4%B8%8D%E8%AF%86%E5%88%AB%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与宏观核算：加总 Solow 残差含再配置（OP 分解）。本课估的是厂级 \\(F\\)，不把宏观 TFP 循环论证。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是信息。计量者看不见 \\(\\omega\\)，但看见与 \\(\\omega\\) 单调的选择。反演把不可观测变成可观测函数，再靠 Markov 把今天的 \\(\\omega\\) 拆成可料与创新，创新与昨天的投入正交。单调失败（投资不可逆、零投资一团）则反演不是函数，LP 的中间投入动机在此。ACF 的要点是：两个灵活投入不能同时在同一阶段从同一个 \\(\\omega\\) 里拆出两个弹性。</p><p>与<a href="/econ/ovb-measurement-error">遗漏变量</a>：\\(\\omega\\) 是相关遗漏。代理方法是针对这一种遗漏的结构，不是通用 IV。资本测量误差仍衰减 \\(\\beta_k\\)——Griliches 的警告还在。</p><p><span class="marginnote">Gandhi–Navarro–Rivers 指出：在某些时序与完全竞争下，弹性识别更薄，要靠风险价格或需求边。本课以 OP/LP/ACF 为最小传统，边界上承认识别争论。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估 CES 宏观加总全文。不把 TFP 差异写成制度质量的因果（那要设计或另一套结构）。下一课拍卖：对象是出价策略与估值分布，不是 \\(F(K,L)\\)。贸易后课的异质企业生产率（Melitz）会用到厂级 \\(\\omega\\) 的分布，但估计装置在本课，贸易机制在后课。</p><p>后课默认：厂级生产函数先写信息时序与代理单调；OLS 弹性默认有偏。ACF 时序不满足时不要报「第一阶段 \\(\\beta_l\\)」。宏观残差分解可以引用 OP，但不替代微观识别。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内生投入：\\(\\omega\\) 进入选择，OLS 高估弹性。</li><li>OP / LP：投资或中间投入反演 \\(\\omega\\)；ACF 纠正劳动时序。</li><li>第二阶段用 Markov 创新的矩。</li><li>测量误差与零投资会破坏反演。</li><li>出处：Olley and Pakes, <em>Econometrica</em> 1996；Levinsohn and Petrin, <em>RES</em> 2003；Ackerberg, Caves and Frazer, <em>Econometrica</em> 2015。</li></ul>',10))])}const b=r(E,[["render",p]]);export{P as __pageData,b as default};
